package com.game_manager.gm.document;
import com.game_manager.gm.document.storage.DocumentStorage; import io.micrometer.core.instrument.MeterRegistry; import java.security.*; import java.util.HexFormat; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component @ConditionalOnProperty(prefix="app.jobs",name="enabled",havingValue="true") public class DocumentReconciliationWorker {private final DocumentVersionRepository versions;private final DocumentStorage storage;private final MeterRegistry metrics;public DocumentReconciliationWorker(DocumentVersionRepository v,DocumentStorage s,MeterRegistry m){versions=v;storage=s;metrics=m;}@Scheduled(fixedDelayString="${app.documents.reconcile-interval-millis:86400000}")@Transactional public void reconcile(){for(DocumentVersion v:versions.findAll()){boolean valid=false;try(var in=storage.open(v.getObjectKey())){valid=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(in.readAllBytes())).equals(v.getChecksumSha256());}catch(Exception ignored){valid=false;}metrics.counter("gmanager.document.reconciliation","result",valid?"match":"mismatch").increment();if(!valid){v.setScanStatus(ScanStatus.ERROR);v.setScanDetail("Storage reconciliation failed");}}}}
